// CSD_RATIONALE_BEGIN
// Math-step CSD with delimiter-aware outside generation and adaptive inside
// generation. The strategy tracks the usual constrained-span state
// (insideConstrainedOut, currentConstrainedOut) plus a local preferred-token
// bag derived from validTokenGroups. Outside a span it generates freely until
// EOS or the open delimiter "<<". Inside a span, if the arithmetic text built
// so far is already a complete parser prefix, it closes immediately with ">>".
// Otherwise it chooses between a tight one-token constrained step and a
// wider ConstrainedSymbol step based on parser narrowness.
//
// When using the wider inside mode, the strategy softly boosts caller-supplied
// preferred tokens that overlap parser-valid candidates, then asks
// ConstrainedSymbol to extend the arithmetic expression for up to
// stepTokenBudget tokens. This keeps arithmetic text inside << >> parser-valid
// while still allowing multi-token progress on easy stretches.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity: In the unconstrained branch, entering a span happens only
//   when the emitted token is "<<", and we set currentConstrainedOut := [],
//   which is valid by the precondition parser.IsValidPrefix([]). In the
//   complete-prefix branch, CloseConstrainedSpan sets insideConstrainedOut to
//   false, so the implication becomes vacuous. In the tight constrained branch,
//   ConstrainedStep returns a parser-valid next token (or EOS, which breaks),
//   and AppendConstrainedToken preserves validity. In the wide constrained
//   branch, ConstrainedSymbol returns currentOut that is itself a valid prefix;
//   assigning currentConstrainedOut := symbolOut preserves the invariant.
// suffix: Outside the span, insideConstrainedOut is false except immediately
//   after seeing "<<", where currentConstrainedOut is [] and the length-0 suffix
//   condition holds trivially. CloseConstrainedSpan appends the close delimiter
//   and resets currentConstrainedOut to [], so the implication is vacuous. In
//   the tight constrained branch, AppendConstrainedToken appends the same token
//   to generated and currentConstrainedOut. In the wide branch, with
//   stablePrefix := generated[..|generated|-|currentConstrainedOut|], we set
//   generated := stablePrefix + symbolOut and currentConstrainedOut := symbolOut,
//   so the final suffix of generated is exactly currentConstrainedOut.
// progress: UnconstrainedStep, CloseConstrainedSpan, and the tight constrained
//   branch each append at most one token and increment steps by 1. The wide
//   constrained branch uses ConstrainedSymbol, which appends from the old
//   currentConstrainedOut to symbolOut and returns stepsUsed; assigning
//   generated := stablePrefix + symbolOut increases |generated| by
//   |symbolOut| - |oldCurrent|, which is bounded by stepsUsed, and then
//   steps := steps + stepsUsed preserves |generated| <= |generatedPrefix| + steps.
// cost accounting: cost stays 0 throughout the loop body and is assigned only
//   once at the end as cost := steps. Every branch either increments steps by
//   exactly the amount of generation work performed (1 for single-step helpers,
//   stepsUsed for ConstrainedSymbol) or breaks immediately, so the final
//   returned cost equals steps and therefore cost <= maxSteps.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps: nat := 0;
var narrowThreshold: nat := 8;
var flatPreferred := helpers.FlattenTokenGroups(validTokenGroups);

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant insideConstrainedOut ==> generated[|generated| - |currentConstrainedOut|..] == currentConstrainedOut
  invariant |generated| <= |generatedPrefix| + steps
  invariant cost == 0
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if next == "<<" {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
  } else {
    if parser.IsCompletePrefix(currentConstrainedOut) {
      var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
        lm, parser, generated, currentConstrainedOut
      );
      generated := closedGenerated;
      insideConstrainedOut := closedInside;
      currentConstrainedOut := closedCurrent;
      steps := steps + 1;
    } else {
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var validCount := helpers.ValidTokenCount(parser, currentConstrainedOut);
      if validCount <= narrowThreshold || stepTokenBudget == 0 {
        var next := helpers.ConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, eosToken);
        steps := steps + 1;
        if next == eosToken {
          break;
        } else {
          var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
            lm, parser, generated, currentConstrainedOut, next
          );
          generated := appendedGenerated;
          insideConstrainedOut := appendedInside;
          currentConstrainedOut := appendedCurrent;
        }
      } else {
        lm.GenerateLogits(constrainedPrompt + currentConstrainedOut);
        if |flatPreferred| > 0 {
          var candidates := helpers.TopValidCandidates(
            lm, parser, constrainedPrompt, currentConstrainedOut, 24, eosToken
          );
          var preferred := helpers.IntersectTokenSets(candidates, flatPreferred);
          if |preferred| > 0 {
            helpers.BoostTokenLogits(lm, preferred, 3.0);
          }
        }

        var stablePrefix := generated[..|generated| - |currentConstrainedOut|];
        var symbolOut, hitEos, stepsUsed := helpers.ConstrainedSymbol(
          lm, parser, constrainedPrompt, currentConstrainedOut, stepTokenBudget, eosToken
        );
        generated := stablePrefix + symbolOut;
        currentConstrainedOut := symbolOut;
        steps := steps + stepsUsed;
        if hitEos {
          break;
        }
      }
    }
  }
}

cost := steps;

